-- booking_28_descriptions ROLLBACK: palauttaa kb 8, 10, 11, 12 kuvaukset (FI/EN) ennen muutosta 17.10.2026 vallinneisiin arvoihin.
update kb.products set description = $o8f$Lyhyt saunotusrituaali hoitosauna Raunissa (enintään kuusi henkeä kerrallaan): löylyntervehdys, kevyttä lämmittelyvihdontaa ja vuodenkierron mukainen minihoito. Voi osallistua uimapuvussa tai alasti. Varattavissa lisäpalveluna yleiselle vuorolle.$o8f$, description_en = $o8e$A short sauna ritual in the Rauni healing sauna (up to six guests at a time): a greeting of the steam (löyly), gentle warming with birch whisks and a mini treatment that follows the turning of the seasons.$o8e$ where id = 8;
update kb.products set description = $o10f$Lempeä mutta syvä pysähdys löylyn, lämmön ja luonnonantimien äärelle. Alkaa löylyntervehdysrituaalilla, jonka jälkeen saunottaja toteuttaa valitun hoidon: hunajahoito, vihtahoito, suolahoito tai turvehoito (valinta kassalla). Varattavissa 1–4 hengelle; sisältö mukautuu ryhmän kokoon. Hoidon hintaan ei sisälly pääsyä savusaunaan tai paljuihin (pääsyliput erikseen). Toteutetaan hoitosauna Raunissa. Saunottajat: Laura Foon, Joonas Vaarala ja Saara Mäntykoski. Hoitoon voi osallistua alasti, osittain tai kokonaan uima-asussa.$o10f$, description_en = null where id = 10;
update kb.products set description = $o11f$Kahden tunnin kokonaisvaltainen saunaelämys: vihdat, kasvit, yrtit, suola ja hunaja, halutessa turvehoito; loitsuja, vihtomista, löylyn, veden ja ilman tekniikoita, kellutus viileässä altaassa ja yrttitee. Saunottaja mukauttaa voimakkuuden asiakkaan mukaan. Varattavissa 1–2 hengelle. Hoidon hintaan ei sisälly pääsyä savusaunaan tai paljuihin (pääsyliput erikseen). Toteutetaan hoitosauna Raunissa. Saunottajat: Laura Foon, Joonas Vaarala ja Saara Mäntykoski. Hoitoon voi osallistua alasti, osittain tai kokonaan uima-asussa.$o11f$, description_en = null where id = 11;
update kb.products set description = $o12f$Kolmen tunnin kokonaisvaltainen saunotusrituaali useassa vaiheessa: vihdat, kasvit, yrtit, suola, hunaja ja halutessa turve; loitsuja, rytmistä vihtomista, lämpimän ja viileän vaihtelua, kellutus viileässä altaassa. Sisältää yrttiteetä ja pientä purtavaa. Varattavissa 1–2 hengelle. Hoidon hintaan ei sisälly pääsyä savusaunaan tai paljuihin (pääsyliput erikseen). Toteutetaan hoitosauna Raunissa. Saunottajat: Laura Foon, Joonas Vaarala ja Saara Mäntykoski. Hoitoon voi osallistua alasti, osittain tai kokonaan uima-asussa.$o12f$, description_en = null where id = 12;
